insert into public.symbolic_associations (id,profile_version_id,category,value,context_note,disclaimer) values
('50000000-0000-4000-8000-000000000001','30000000-0000-4000-8000-000000000001','Image culturelle','Le livre ouvert','Une évocation de l’univers littéraire d’Alice au pays des merveilles ; cette image relève d’une lecture culturelle et ne décrit pas les personnes qui portent le prénom.','Interprétation symbolique ou culturelle, sans valeur scientifique ou prédictive.'),
('50000000-0000-4000-8000-000000000002','30000000-0000-4000-8000-000000000002','Figure religieuse','Le messager','Évocation de la figure de Gabriel dans plusieurs traditions religieuses ; les récits et interprétations diffèrent selon les traditions.','Interprétation symbolique ou culturelle, sans valeur scientifique ou prédictive.'),
('50000000-0000-4000-8000-000000000003','30000000-0000-4000-8000-000000000003','Image éditoriale','L’élan','Association libre inspirée d’une piste étymologique germanique souvent rapprochée de l’idée de grandeur ; elle ne constitue pas une signification certaine.','Interprétation symbolique ou culturelle, sans valeur scientifique ou prédictive.'),
('50000000-0000-4000-8000-000000000004','30000000-0000-4000-8000-000000000004','Repère historique','La couronne','Évocation de l’histoire monarchique française associée à plusieurs souverains prénommés Louis.','Interprétation symbolique ou culturelle, sans valeur scientifique ou prédictive.'),
('50000000-0000-4000-8000-000000000005','30000000-0000-4000-8000-000000000005','Motif naturel','Le tilleul','Évocation d’une piste germanique qui rapproche lind du tilleul ; l’origine du prénom Lina reste plurielle et discutée.','Interprétation symbolique ou culturelle, sans valeur scientifique ou prédictive.'),
('50000000-0000-4000-8000-000000000006','30000000-0000-4000-8000-000000000006','Récit biblique','L’arche','Référence au récit de Noé dans la Genèse ; image religieuse et culturelle, sans portée prédictive.','Interprétation symbolique ou culturelle, sans valeur scientifique ou prédictive.')
